export const pages120BySlug = all120Pages.reduce((acc, page) => {
  acc[page.slug] = page;
  return acc;
}, {});

export const getPageBySlug = (slug) => {
  if (!slug) return null;
  const clean = slug.replace(/^\//, '').replace(/\/$/, '');
  return pages120BySlug[clean] || null;
};

